<script setup>
import { computed, onMounted, reactive, ref, watch } from "vue";
import SearchableSelect from "@/components/form/SearchableSelect.vue";
const props = defineProps({ grievance: { type: Object, default: null }, departments: { type: Array, default: () => [] }, sectors: { type: Array, default: () => [] }, loading: Boolean, error: { type: String, default: "" } });
const emit = defineEmits(["submit", "cancel"]); const files = ref([]); const picker = ref(null);
const form = reactive({ title: "", sector_id: "", department_id: "", description: "", status: "submitted", complained_at: "", due_at: "" });
const statusOptions = [{ value: "submitted", label: "Soumise" }, { value: "rejected", label: "Rejetée" }, { value: "in_progress", label: "En cours" }, { value: "processed", label: "Traitée" }];
const isEdit = computed(() => Boolean(props.grievance)); const sectorOptions = computed(() => props.sectors.map((item) => ({ value: item.id, label: item.name }))); const departmentOptions = computed(() => props.departments.map((item) => ({ value: item.id, label: item.name })));
function localDate(value) { if (!value) return ""; const date = new Date(value); const pad = (n) => String(n).padStart(2, "0"); return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`; }
function nowLocal() { return localDate(new Date()); } function plus48Hours(value) { const date = value ? new Date(value) : new Date(); date.setHours(date.getHours() + 48); return localDate(date); }
watch(() => props.grievance, (item) => { form.title = item?.title || ""; form.sector_id = item?.sector?.id || ""; form.department_id = item?.department?.id || ""; form.description = item?.description || ""; form.status = item?.status || "submitted"; form.complained_at = localDate(item?.complained_at) || nowLocal(); form.due_at = localDate(item?.due_at) || plus48Hours(form.complained_at); files.value = []; }, { immediate: true });
function validateDueDate() { if (!form.due_at || form.due_at <= form.complained_at) form.due_at = plus48Hours(form.complained_at); }
function addFiles(event) { const incoming = [...event.target.files]; files.value = [...files.value, ...incoming.filter((file) => !files.value.some((oldFile) => oldFile.name === file.name && oldFile.size === file.size))]; event.target.value = ""; }
function removeFile(index) { files.value.splice(index, 1); }
function submit() { emit("submit", { ...form, sector_id: Number(form.sector_id), department_id: form.department_id ? Number(form.department_id) : null, documents: files.value }); }
onMounted(() => { const input = document.querySelector('input[type="file"]'); input?.setAttribute("accept", "*/*"); const hint = input?.closest("label")?.querySelector("small"); if (hint && !files.value.length) hint.textContent = "Tous les formats courants · 50 Mo maximum par fichier"; });
</script>
<template>
  <form class="form-card" @submit.prevent="submit"><div class="form-intro"><span class="form-icon">!</span><div><h3>{{ isEdit ? "Modifier la doléance" : "Nouvelle doléance" }}</h3><p>Les dates sont préremplies et contrôlées automatiquement.</p></div></div><div v-if="error" class="alert">{{ error }}</div><div class="form-grid"><label class="wide">Titre<input v-model.trim="form.title" required maxlength="255" placeholder="Ex. Éclairage public défectueux" /></label><label>Secteur<SearchableSelect v-model="form.sector_id" :options="sectorOptions" required placeholder="Rechercher un secteur" /></label><label>Attribution<SearchableSelect v-model="form.department_id" :options="departmentOptions" placeholder="Rechercher un département" /></label><label class="wide">Description<textarea v-model.trim="form.description" required rows="5" placeholder="Décrivez la doléance…" /></label><label>Statut<select v-model="form.status"><option v-for="status in statusOptions" :key="status.value" :value="status.value">{{ status.label }}</option></select></label><label>Date de la doléance<input v-model="form.complained_at" type="datetime-local" required @change="validateDueDate" /><small>Par défaut : maintenant</small></label><label>Date d’échéance<input v-model="form.due_at" type="datetime-local" :min="form.complained_at" /><small>Par défaut : 48 h après la doléance</small></label><label class="wide file-label">Documents<input ref="picker" type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,.txt" @change="addFiles" /><button type="button" class="add-file" @click="picker?.click()">＋ Ajouter des fichiers</button><small>{{ files.length ? `${files.length} fichier(s) sélectionné(s)` : "PDF, Word, Excel ou image · 10 Mo maximum par fichier" }}</small><ul v-if="files.length" class="file-list"><li v-for="(file, index) in files" :key="`${file.name}-${file.size}-${index}`"><span>{{ file.name }}</span><button type="button" @click="removeFile(index)">Retirer</button></li></ul></label></div><div class="form-actions"><button type="button" class="secondary-button" @click="$emit('cancel')">Annuler</button><button type="submit" class="submit-button" :disabled="loading">{{ loading ? "Enregistrement…" : isEdit ? "Enregistrer les changements" : "Créer la doléance" }} <span>→</span></button></div></form>
</template>
<style scoped>
.form-card{display:grid;max-width:900px;gap:1.15rem;padding:1.4rem;border:1px solid #e8eef6;border-radius:.9rem;background:#fff;box-shadow:0 5px 15px rgb(30 52 84 / 3%)}.form-intro{display:flex;align-items:center;gap:.75rem}.form-icon{display:grid;width:2.35rem;height:2.35rem;place-items:center;border-radius:.7rem;color:#fff;background:linear-gradient(135deg,#5b8cff,#7c3aed);font-weight:800}.form-intro h3{margin:0;color:#253650;font-size:.9rem}.form-intro p{margin:.25rem 0 0;color:#98a5b5;font-size:.7rem}.alert{padding:.7rem .8rem;border:1px solid #ffd7db;border-radius:.5rem;color:#b33e4b;background:#fff3f4;font-size:.75rem}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.form-grid label{display:grid;gap:.45rem;color:#53647c;font-size:.72rem;font-weight:700}.form-grid .wide{grid-column:1/-1}.form-grid input,.form-grid select,.form-grid textarea{width:100%;padding:.75rem .8rem;border:1px solid #dce4ef;border-radius:.5rem;outline:0;color:#30415a;background:#fff;font-size:.78rem;resize:vertical}.form-grid small{color:#9aa7b7;font-size:.64rem;font-weight:400}.file-label input[type=file]{padding:.55rem;background:#f8faff}.add-file{width:max-content;padding:0;border:0;color:#4776da;background:none;font-size:.69rem;font-weight:700;cursor:pointer}.file-list{display:grid;gap:.35rem;margin:0;padding:0;list-style:none}.file-list li{display:flex;align-items:center;justify-content:space-between;gap:.5rem;padding:.45rem .6rem;border-radius:.4rem;background:#f7f9fc;font-size:.68rem}.file-list span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.file-list button{border:0;color:#bd5a66;background:none;font-size:.65rem;font-weight:700;cursor:pointer}.form-actions{display:flex;justify-content:flex-end;gap:.65rem}.submit-button,.secondary-button{padding:.75rem 1rem;border:0;border-radius:.5rem;font-size:.72rem;font-weight:700;cursor:pointer}.submit-button{color:#fff;background:linear-gradient(100deg,#3e70da,#5c82e4)}.secondary-button{color:#68788e;background:#f1f4f8}.submit-button:disabled{opacity:.6}@media(max-width:620px){.form-grid{grid-template-columns:1fr}.form-grid .wide{grid-column:auto}.form-actions{flex-direction:column-reverse}.form-actions button{width:100%}}
</style>
